// The details a pro types at verification, in plain words: what each should look like, and the box keeping only what can fit. Websites and apps alike.
const letters = (n) => (v) => String(v || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, n);

const RULES = {
  pan_number: { clean: letters(10), max: 10, caps: true, help: 'PAN has 10 characters: 5 letters, 4 numbers, 1 letter. Example: ABCDE1234F' },
  gst_number: { clean: letters(15), max: 15, caps: true, help: 'GST number has 15 characters. Example: 36ABCDE1234F1Z5' },
  years_active: { clean: (v) => String(v || '').replace(/\D/g, '').slice(0, 2), max: 2, numeric: true, help: 'Write a number, like 5' },
};

export const detailRule = (code) => RULES[code] || null;

/** What the box keeps of what was typed (PAN in capitals, no symbols; years as a number). */
export const cleanDetail = (code, value) => (RULES[code] ? RULES[code].clean(value) : String(value ?? ''));

/** What to show under a detail that was not right. */
export const detailHelp = (field) => RULES[field?.code]?.help || field?.hint || 'This does not look right. Please check it.';

/** One line naming what is still needed: "Please add: Shop photo, Selfie". */
export function missingLine(missing = []) {
  const names = missing.map((m) => m.label || String(m.code || '').replace(/_/g, ' ')).filter(Boolean);
  return names.length ? `Please add: ${names.join(', ')}` : 'Some items are still needed';
}

/** One line naming what to fix: "Please fix your PAN number". */
export function fixLine(fields = []) {
  const names = fields.map((f) => f.label || String(f.code || '').replace(/_/g, ' ')).filter(Boolean);
  return names.length ? `Please fix your ${names.join(' and ')}` : 'Please check your details';
}
